import{z as s,x as l,o as B,c as C,q as o,j as r,D as A,d as a,s as t,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"环境经济学收束","description":"","frontmatter":{"title":"环境经济学收束","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/env-map.md","filePath":"econ/env-map.md","lastUpdated":1791063341000}'),d={name:"econ/env-map.md"};function p(c,E,D,m,h,f){const n=l("Mermaid");return B(),C("div",null,[E[2]||(E[2]=o('<h1 id="环境经济学收束" tabindex="-1">环境经济学收束 <a class="header-anchor" href="#环境经济学收束" aria-label="Permalink to &quot;环境经济学收束&quot;">​</a></h1><div class="epigraph"><p>外部性课程的终点是一个没有世界政府的公共品问题：所有工具都在境内生效，而损害在全球积累。</p><footer>—— Coase 1960；Weitzman 1974；Nordhaus 2017 的共同追问</footer></div><p><a href="/econ/env-climate-finance">上一课</a>把贴现率从模型参数换成资本成本，工具箱到此装满。本课收束：把七课连成一张地图，看哪些问题是同一个问题的不同投影、哪些边界是全课程共有的。本课程到此收束。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>回望课程，环境经济学的全部工具都在回答同一个三元组：楔在哪（价格还是数量）、楔多深（SCC 或帽高）、谁付钱（分配、边境与金融）。<a href="/econ/pigouvian-carbon-price">庇古税与碳定价</a>给了一阶答案；本课程把这个答案放进日历、放进电网、放进贸易与资本市场。收束不是复述各课，是找到把七课串起来的最小骨架——找不到骨架，七课只是七篇独立的综述，后面的任何加深都无处挂靠。</p><p><span class="marginnote">直觉类比：把气候政策想成给一条超载的路设卡。是设收费站还是限流放行（价格还是数量）？收多贵、放多少车（SCC 或帽高）？收来的钱归谁花（分配、边境与金融）？三个问题问全，任何一份气候政策的底牌就翻完了。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三条线。时空线：静态庇古楔（碳价等于当期边际损害），经跨期可信的帽（<a href="/econ/env-ets-deep">排放交易体系的深化</a>），到移动的 MAC（<a href="/econ/env-energy-transition">能源转型经济学</a>）——同一个楔子的时间维度逐课展开。物理线：学习曲线把成本打下去，电网物理把市场设计重写（<a href="/econ/env-power-markets">电力市场设计</a>）——抽象的减排成本落到具体的出清价。边界线：泄漏把政策推到口岸（<a href="/econ/env-cbam">碳边境调节</a>），政治把第二楔子推上桌（<a href="/econ/env-subsidy-design">补贴的设计</a>），金融把贴现率推成成本（<a href="/econ/env-climate-finance">气候金融</a>）——每一课的边界都是下一课的问题。</p>',8)),(B(),r(i,null,{default:A(()=>[t(n,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20PIG%5B%22%E5%BA%87%E5%8F%A4%E6%A5%94%3A%20SCC%20%E4%B8%8E%20Weitzman%20%E5%88%A4%E6%8D%AE%22%5D%20--%3E%20ETS%5B%22ETS%3A%20%E8%B7%A8%E6%9C%9F%E5%8F%AF%E4%BF%A1%E7%9A%84%E5%B8%BD%22%5D%0A%20%20ETS%20--%3E%20TRANS%5B%22%E8%BD%AC%E5%9E%8B%3A%20%E7%A7%BB%E5%8A%A8%E7%9A%84%20MAC%22%5D%0A%20%20TRANS%20--%3E%20POWER%5B%22%E7%94%B5%E5%8A%9B%3A%20%E7%89%A9%E7%90%86%E7%BA%A6%E6%9D%9F%E4%B8%8B%E7%9A%84%E5%B8%82%E5%9C%BA%22%5D%0A%20%20ETS%20--%3E%20CBAM%5B%22%E8%BE%B9%E5%A2%83%3A%20%E5%B0%81%E5%A0%B5%E6%B3%84%E6%BC%8F%22%5D%0A%20%20TRANS%20--%3E%20SUB%5B%22%E8%A1%A5%E8%B4%B4%3A%20%E7%AC%AC%E4%BA%8C%E6%A5%94%E5%AD%90%22%5D%0A%20%20SUB%20--%3E%20FIN%5B%22%E9%87%91%E8%9E%8D%3A%20%E8%B4%B4%E7%8E%B0%E7%8E%87%E5%8D%B3%E6%88%90%E6%9C%AC%22%5D%0A%20%20POWER%20--%3E%20FIN%0A%20%20FIN%20--%3E%20MAP%5B%22%E6%94%B6%E6%9D%9F%3A%20%E6%97%B6%E7%A9%BA%2F%E7%89%A9%E7%90%86%2F%E8%BE%B9%E7%95%8C%E4%B8%89%E6%9D%A1%E7%BA%BF%22%5D%0A"})]),fallback:A(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[a("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,[a("这套工具族为什么自洽：它们都在把同一个外部性的影子价格写进某个决策者的约束——碳价写进边际成本，帽子写进稀缺租，边境写进进口价，披露写进资本成本；差别只在写入的位置与可信度。可信度为什么是全课程的公共参数：帽子要 MSR 与规则化退坡才可信，补贴退坡要写进法条才可信，千亿美元的资金承诺要十三年才兑现——"),e("a",{href:"/econ/coase-theorem"},"科斯定理"),a("的交易成本口径换了名目仍在场。实证为什么不能缺席：泄漏幅度、学习率、绿色溢价、融资成本差，每个参数都是经验问题，证据口径见 "),e("a",{href:"/econ/ca-env-policy-evidence"},"环境政策的实证证据"),a("——工具选得再对，参数错了照样错。")],-1)),(B(),r(i,null,{default:A(()=>[t(n,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20EXT%5B%22%E5%90%8C%E4%B8%80%E4%B8%AA%E6%8E%92%E6%94%BE%E5%A4%96%E9%83%A8%E6%80%A7%22%5D%20--%3E%20Q%7B%22%E5%BD%B1%E5%AD%90%E4%BB%B7%E6%A0%BC%E5%86%99%E8%BF%9B%E8%B0%81%E7%9A%84%E7%BA%A6%E6%9D%9F%EF%BC%9F%22%7D%0A%20%20Q%20--%3E%7C%22%E7%A2%B3%E4%BB%B7%22%7C%20FIRM%5B%22%E4%BC%81%E4%B8%9A%E8%BE%B9%E9%99%85%E6%88%90%E6%9C%AC%20%E2%86%92%20%E7%94%9F%E4%BA%A7%E5%86%B3%E7%AD%96%22%5D%0A%20%20Q%20--%3E%7C%22%E5%B8%BD%E5%AD%90%22%7C%20SCARCE%5B%22%E7%A8%80%E7%BC%BA%E7%A7%9F%20%E2%86%92%20%E9%85%8D%E9%A2%9D%E6%8C%81%E6%9C%89%E5%86%B3%E7%AD%96%22%5D%0A%20%20Q%20--%3E%7C%22%E8%BE%B9%E5%A2%83%E7%A8%8E%22%7C%20IMP%5B%22%E8%BF%9B%E5%8F%A3%E4%BB%B7%E6%A0%BC%20%E2%86%92%20%E9%80%89%E5%9D%80%E5%86%B3%E7%AD%96%22%5D%0A%20%20Q%20--%3E%7C%22%E6%8A%AB%E9%9C%B2%22%7C%20INV%5B%22%E8%B5%84%E6%9C%AC%E6%88%90%E6%9C%AC%20%E2%86%92%20%E6%8A%95%E8%B5%84%E5%86%B3%E7%AD%96%22%5D%0A%20%20FIRM%20--%3E%20CRED%5B%22%E5%B7%AE%E5%88%AB%E5%8F%AA%E5%9C%A8%E5%86%99%E5%85%A5%E4%BD%8D%E7%BD%AE%E4%B8%8E%E5%8F%AF%E4%BF%A1%E5%BA%A6%22%5D%0A%20%20SCARCE%20--%3E%20CRED%0A%20%20IMP%20--%3E%20CRED%0A%20%20INV%20--%3E%20CRED%0A"})]),fallback:A(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=o('<p><span class="marginnote">收束检查清单：见到任何气候政策，先问四件事——楔在价格还是数量；时间上可不可信；边界上封没封住；钱由谁的贴现率决定。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>全课程共有的边界三条。非凸与临界点：越过不可逆阈值后边际工具失去定义，SCC 应作为厚尾分布报告（Weitzman 2009 的警告），点估计的确定性是假的。无世界政府：气候是全球公共品（<a href="/econ/public-goods">公共物品</a>的极端形态），一切工具都只能是主权国家的自选动作加协调，边境调节与碳俱乐部是对这一事实的让步，不是解决。跨代分配：贴现率的伦理没有技术答案，只有明示假设的纪律——Nordhaus 2017 展示过参数差零点几个百分点、结论翻几倍的杠杆。这三条边界不因工具进步而消失，只会随着损害逼近而变窄。</p><p><span class="marginnote">数字实例：对 100 年后的 1 元损害，按 3% 贴现今天只值约 5 分钱；按 1.5% 贴现值 2 角 2 分——差 1.5 个百分点，「今天该花多少钱防灾」的答案差出 4 倍。贴现率没有技术答案，但假设必须摆在桌面上。</span></p><p><span class="marginnote">常见误区：把 SCC（碳的社会成本）当成查表可得的自然常数。它对贴现率、损害函数与厚尾处理极其敏感，越过不可逆临界点后边际工具甚至失去定义——负责任的报告给分布与区间，不给一个假装确定的点。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>全部工具是同一个三元组：楔在哪、楔多深、谁付钱；差别只在写入位置与可信度。</li><li>时空线、物理线、边界线把七课连成一张地图，每课的边界是下一课的问题。</li><li>可信度是公共参数：帽子、退坡、资金承诺都靠规则化维持，靠政治自觉必输。</li><li>三条共有边界：非凸临界点、无世界政府、跨代贴现的伦理。</li><li>本课程到此收束：后遇加深课题，回到这张地图找挂靠点。</li><li>出处：Pigou 1920；Coase 1960；Weitzman 1974、2009；Nordhaus 2017；实证口径见各课所引。</li></ul>',7))])}const S=s(d,[["render",p]]);export{F as __pageData,S as default};
